"use strict";
/*
 * Runs inside VSCode's built-in Markdown preview webview.
 * - Renders diagram blocks (mermaid/flowchart/...) generated by markdownItPlugins.
 * - Applies the selected CommonMark theme.
 */
(function () {
  // message pump for diagram rendering triggered from extension host
  function renderDiagrams(root) {
    const blocks = (root || document).querySelectorAll(".commonmark-diagram");
    if (!blocks.length || typeof mermaid === "undefined") {
      return;
    }
    blocks.forEach((block) => {
      const src = block.querySelector(".mermaid-source");
      if (!src || block.dataset.rendered === "true") return;
      const code = src.textContent.trim();
      if (!code) return;
      const lang = block.dataset.lang || "mermaid";
      try {
        if (typeof mermaid !== "undefined") {
          const el = document.createElement("div");
          el.className = "mermaid";
          el.textContent = code;
          block.appendChild(el);
          mermaid.initialize({ startOnLoad: false, theme: "default", securityLevel: "loose" });
          mermaid.parseError = function () {};
          mermaid.run({ nodes: [el] }).then(() => {
            block.dataset.rendered = "true";
          }).catch(() => {
            block.innerHTML = `<pre class="hljs"><code class="language-${lang}">${code.replace(/</g, "&lt;")}</code></pre>`;
            block.dataset.rendered = "true";
          });
        }
      } catch (e) {
        block.innerHTML = `<pre><code>${code.replace(/</g, "&lt;")}</code></pre>`;
        block.dataset.rendered = "true";
      }
    });
  }

  // Listen for theme change messages from the extension host
  window.addEventListener("message", (event) => {
    const msg = event.data;
    if (msg && msg.type === "commonmark-theme") {
      setTheme(msg.theme);
    }
  });

  function setTheme(theme) {
    document.body.dataset.commonmarkTheme = theme || "github";
  }

  // initial render
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => renderDiagrams(document));
  } else {
    renderDiagrams(document);
  }

  // Observe DOM changes for newly added content
  const observer = new MutationObserver(() => renderDiagrams(document));
  observer.observe(document.body, { childList: true, subtree: true });

  // expose
  window.__commonmarkRender = renderDiagrams;
})();
